alter table public.buyers add column if not exists user_id uuid references auth.users(id) on delete restrict;
alter table public.buyers add constraint buyers_user_id_uq unique(user_id);
alter table public.sales add column if not exists order_number text;
alter table public.sales add column if not exists order_kind text not null default 'purchase' check(order_kind in ('purchase','offer','auction','commission'));
alter table public.sales add column if not exists buyer_user_id uuid references auth.users(id) on delete restrict;
alter table public.sales add column if not exists offer_id uuid;
alter table public.sales add column if not exists reservation_id uuid;
alter table public.sales add column if not exists price_snapshot jsonb not null default '{}'::jsonb;
alter table public.sales add column if not exists state_version bigint not null default 1 check(state_version>0);
alter table public.sales add column if not exists cancelled_at timestamptz;
alter table public.sales add column if not exists cancellation_reason text;
create unique index if not exists sales_order_number_uq on public.sales(order_number) where order_number is not null;
create index if not exists sales_buyer_user_idx on public.sales(buyer_user_id,created_at desc) where buyer_user_id is not null;
alter table public.settlements add column if not exists state_version bigint not null default 1 check(state_version>0);
alter table public.shipments add column if not exists state_version bigint not null default 1 check(state_version>0);
alter table public.certificates add column if not exists issuer_artist_id uuid references public.artist_profiles(id) on delete restrict;
alter table public.certificates add column if not exists issue_date date;
alter table public.certificates add column if not exists certificate_version integer not null default 1 check(certificate_version>0);
alter table public.certificates add column if not exists verification_token_hash text;
alter table public.certificates add column if not exists revoked_at timestamptz;
alter table public.certificates add column if not exists revocation_reason text;
create unique index if not exists certificates_verification_token_uq on public.certificates(verification_token_hash) where verification_token_hash is not null;
alter table public.artist_representations add column if not exists can_negotiate_offers boolean not null default false;
alter table public.artist_representations add column if not exists can_manage_shipping boolean not null default false;
alter table public.artist_representations add column if not exists commission_rule_id uuid references public.commission_rules(id) on delete restrict;

create table public.wishlist_items(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,artwork_id uuid not null references public.artworks(id) on delete cascade,created_at timestamptz not null default now(),unique(user_id,artwork_id));
create index wishlist_items_user_idx on public.wishlist_items(user_id,created_at desc);
create table public.recently_viewed_artworks(user_id uuid not null references auth.users(id) on delete cascade,artwork_id uuid not null references public.artworks(id) on delete cascade,last_viewed_at timestamptz not null default now(),view_count integer not null default 1 check(view_count>0),primary key(user_id,artwork_id));
create index recently_viewed_user_idx on public.recently_viewed_artworks(user_id,last_viewed_at desc);
create table public.shopping_bags(id uuid primary key default gen_random_uuid(),user_id uuid not null unique references auth.users(id) on delete cascade,currency char(3) not null default 'INR' check(currency ~ '^[A-Z]{3}$'),created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.shopping_bag_items(id uuid primary key default gen_random_uuid(),bag_id uuid not null references public.shopping_bags(id) on delete cascade,artwork_id uuid not null references public.artworks(id) on delete cascade,price_seen_paise bigint check(price_seen_paise>=0),created_at timestamptz not null default now(),unique(bag_id,artwork_id));

create table public.offers(id uuid primary key default gen_random_uuid(),artwork_id uuid not null references public.artworks(id) on delete restrict,buyer_user_id uuid not null references auth.users(id) on delete restrict,status text not null default 'submitted' check(status in ('submitted','under_review','sent_to_artist','countered','accepted','rejected','withdrawn','expired')),currency char(3) not null default 'INR' check(currency ~ '^[A-Z]{3}$'),amount_paise bigint not null check(amount_paise>0),current_amount_paise bigint not null check(current_amount_paise>0),message text,expires_at timestamptz not null,accepted_sale_id uuid references public.sales(id) on delete restrict,state_version bigint not null default 1 check(state_version>0),created_at timestamptz not null default now(),updated_at timestamptz not null default now(),check(status<>'accepted' or accepted_sale_id is not null));
create index offers_buyer_idx on public.offers(buyer_user_id,created_at desc);create index offers_artwork_open_idx on public.offers(artwork_id,status) where status in ('submitted','under_review','sent_to_artist','countered');
create table public.offer_events(id uuid primary key default gen_random_uuid(),offer_id uuid not null references public.offers(id) on delete restrict,actor_id uuid references auth.users(id) on delete restrict,action text not null,from_status text,to_status text not null,amount_paise bigint check(amount_paise is null or amount_paise>0),note text,metadata jsonb not null default '{}'::jsonb,created_at timestamptz not null default now());
create index offer_events_offer_idx on public.offer_events(offer_id,created_at);
create table public.artwork_reservations(id uuid primary key default gen_random_uuid(),artwork_id uuid not null references public.artworks(id) on delete restrict,user_id uuid not null references auth.users(id) on delete restrict,offer_id uuid references public.offers(id) on delete restrict,sale_id uuid references public.sales(id) on delete restrict,source text not null check(source in ('direct','offer','bag')),status text not null default 'active' check(status in ('pending','active','released','cancelled','expired','converted')),expires_at timestamptz not null,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create unique index artwork_reservation_active_uq on public.artwork_reservations(artwork_id) where status in ('pending','active');create index artwork_reservation_user_idx on public.artwork_reservations(user_id,created_at desc);
alter table public.sales add constraint sales_offer_fk foreign key(offer_id) references public.offers(id) on delete restrict;
alter table public.sales add constraint sales_reservation_fk foreign key(reservation_id) references public.artwork_reservations(id) on delete restrict;

create table public.payment_intents(id uuid primary key default gen_random_uuid(),sale_id uuid not null references public.sales(id) on delete restrict,idempotency_key uuid not null unique,provider text,status text not null default 'created' check(status in ('created','requires_action','processing','succeeded','failed','cancelled','partially_refunded','refunded')),amount_paise bigint not null check(amount_paise>0),currency char(3) not null check(currency ~ '^[A-Z]{3}$'),provider_reference text,created_by uuid not null references auth.users(id) on delete restrict,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(provider,provider_reference));
create index payment_intents_sale_idx on public.payment_intents(sale_id,created_at desc);
create table public.payment_attempts(id uuid primary key default gen_random_uuid(),intent_id uuid not null references public.payment_intents(id) on delete restrict,attempt_number integer not null check(attempt_number>0),status text not null,provider_reference text,response_code text,failure_code text,created_at timestamptz not null default now(),unique(intent_id,attempt_number));
create table public.payment_events(id uuid primary key default gen_random_uuid(),intent_id uuid references public.payment_intents(id) on delete restrict,provider text not null,provider_event_id text not null,event_type text not null,amount_paise bigint check(amount_paise is null or amount_paise>=0),currency char(3),signature_verified boolean not null default false,payload_sha256 text not null,received_at timestamptz not null default now(),processed_at timestamptz,processing_error text,unique(provider,provider_event_id));
create table public.refund_requests(id uuid primary key default gen_random_uuid(),sale_id uuid not null references public.sales(id) on delete restrict,payment_intent_id uuid references public.payment_intents(id) on delete restrict,amount_paise bigint not null check(amount_paise>0),currency char(3) not null default 'INR',status text not null default 'requested' check(status in ('requested','approved','processing','succeeded','failed','rejected','cancelled')),reason text not null,requested_by uuid not null references auth.users(id) on delete restrict,provider_reference text,idempotency_key uuid not null unique,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.financial_ledger_entries(id uuid primary key default gen_random_uuid(),transaction_id uuid not null,sale_id uuid references public.sales(id) on delete restrict,payment_intent_id uuid references public.payment_intents(id) on delete restrict,settlement_id uuid references public.settlements(id) on delete restrict,entry_type text not null,account text not null,direction text not null check(direction in ('debit','credit')),amount_paise bigint not null check(amount_paise>0),currency char(3) not null check(currency ~ '^[A-Z]{3}$'),idempotency_key text not null,reference text,metadata jsonb not null default '{}'::jsonb,posted_at timestamptz not null default now(),unique(idempotency_key,account,direction,entry_type));
create index ledger_transaction_idx on public.financial_ledger_entries(transaction_id);create index ledger_sale_idx on public.financial_ledger_entries(sale_id,posted_at);
create table public.intermediary_commissions(id uuid primary key default gen_random_uuid(),sale_id uuid not null references public.sales(id) on delete restrict,representation_id uuid not null references public.artist_representations(id) on delete restrict,intermediary_id uuid not null references public.intermediary_profiles(id) on delete restrict,rule_snapshot jsonb not null,amount_paise bigint not null check(amount_paise>=0),currency char(3) not null default 'INR',status text not null default 'pending' check(status in ('pending','approved','payable','settled','held','cancelled')),approved_by uuid references auth.users(id) on delete restrict,approved_at timestamptz,settlement_id uuid references public.settlements(id) on delete restrict,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(sale_id,representation_id));
create table public.settlement_events(id uuid primary key default gen_random_uuid(),settlement_id uuid not null references public.settlements(id) on delete restrict,actor_id uuid references auth.users(id) on delete restrict,from_status text,to_status text not null,amount_paise bigint not null check(amount_paise>=0),reference text,note text,created_at timestamptz not null default now());
create table public.shipment_events(id uuid primary key default gen_random_uuid(),shipment_id uuid not null references public.shipments(id) on delete restrict,actor_id uuid references auth.users(id) on delete restrict,from_status text,to_status text not null,courier text,tracking_reference text,note text,created_at timestamptz not null default now());
create table public.certificate_events(id uuid primary key default gen_random_uuid(),certificate_id uuid not null references public.certificates(id) on delete restrict,actor_id uuid references auth.users(id) on delete restrict,action text not null,version integer not null check(version>0),note text,created_at timestamptz not null default now());

create table public.notifications(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,category text not null,subject text not null,body text not null default '',link text,dedupe_key text not null,read_at timestamptz,created_at timestamptz not null default now(),unique(user_id,dedupe_key));
create index notifications_user_idx on public.notifications(user_id,read_at,created_at desc);
create table public.notification_preferences(user_id uuid not null references auth.users(id) on delete cascade,category text not null,in_app_enabled boolean not null default true,email_enabled boolean not null default false,updated_at timestamptz not null default now(),primary key(user_id,category));
create table public.notification_deliveries(id uuid primary key default gen_random_uuid(),notification_id uuid not null references public.notifications(id) on delete restrict,channel text not null check(channel in ('email','in_app')),status text not null default 'pending' check(status in ('pending','processing','delivered','failed','cancelled')),idempotency_key text not null unique,provider_reference text,attempt_count integer not null default 0 check(attempt_count>=0),next_attempt_at timestamptz,last_error text,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.private_media_assets(id uuid primary key default gen_random_uuid(),owner_user_id uuid not null references auth.users(id) on delete restrict,purpose text not null check(purpose in ('artist_verification','legal_agreement','certificate','order_document','shipping_document','operational_attachment')),storage_provider text not null,storage_key text not null unique,original_filename text not null,mime_type text not null,file_size_bytes bigint not null check(file_size_bytes between 1 and 26214400),sha256 text not null,scan_status text not null default 'pending' check(scan_status in ('pending','clean','rejected','failed')),revoked_at timestamptz,created_at timestamptz not null default now());
create table public.private_media_access_events(id uuid primary key default gen_random_uuid(),asset_id uuid not null references public.private_media_assets(id) on delete restrict,actor_id uuid references auth.users(id) on delete restrict,action text not null check(action in ('upload_requested','uploaded','viewed','downloaded','revoked','scan_result')),created_at timestamptz not null default now());
create table public.operational_exceptions(id uuid primary key default gen_random_uuid(),domain text not null,entity_type text not null,entity_id uuid,severity text not null check(severity in ('info','warning','critical')),status text not null default 'open' check(status in ('open','investigating','resolved','dismissed')),code text not null,detail text not null,assigned_to uuid references auth.users(id) on delete restrict,resolved_at timestamptz,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create index operational_exceptions_queue_idx on public.operational_exceptions(status,severity,created_at);

do $$declare t text;begin foreach t in array array['wishlist_items','recently_viewed_artworks','shopping_bags','shopping_bag_items','offers','offer_events','artwork_reservations','payment_intents','payment_attempts','payment_events','refund_requests','financial_ledger_entries','intermediary_commissions','settlement_events','shipment_events','certificate_events','notifications','notification_preferences','notification_deliveries','private_media_assets','private_media_access_events','operational_exceptions'] loop execute format('alter table public.%I enable row level security',t);end loop;end$$;
create policy wishlist_own_read on public.wishlist_items for select to authenticated using(user_id=auth.uid() and public.tra_account_is_active());
create policy recent_own_read on public.recently_viewed_artworks for select to authenticated using(user_id=auth.uid() and public.tra_account_is_active());
create policy bags_own_read on public.shopping_bags for select to authenticated using(user_id=auth.uid() and public.tra_account_is_active());
create policy bag_items_own_read on public.shopping_bag_items for select to authenticated using(exists(select 1 from public.shopping_bags b where b.id=bag_id and b.user_id=auth.uid()) and public.tra_account_is_active());
create policy offers_party_read on public.offers for select to authenticated using(public.tra_account_is_active() and (buyer_user_id=auth.uid() or public.tra_has_permission('offers.manage') or exists(select 1 from public.artworks a where a.id=artwork_id and public.tra_owns_artist(a.artist_id))));
create policy offer_events_party_read on public.offer_events for select to authenticated using(exists(select 1 from public.offers o where o.id=offer_id and (o.buyer_user_id=auth.uid() or public.tra_has_permission('offers.manage') or exists(select 1 from public.artworks a where a.id=o.artwork_id and public.tra_owns_artist(a.artist_id)))));
create policy reservations_party_read on public.artwork_reservations for select to authenticated using(public.tra_account_is_active() and (user_id=auth.uid() or public.tra_has_permission('orders.manage') or exists(select 1 from public.artworks a where a.id=artwork_id and public.tra_owns_artist(a.artist_id))));
create policy notifications_own_read on public.notifications for select to authenticated using(user_id=auth.uid() and public.tra_account_is_active());
create policy preferences_own_read on public.notification_preferences for select to authenticated using(user_id=auth.uid() and public.tra_account_is_active());
create policy private_media_owner_read on public.private_media_assets for select to authenticated using(owner_user_id=auth.uid() and public.tra_account_is_active());
create policy finance_payment_read on public.payment_intents for select to authenticated using(public.tra_has_permission('payments.manage'));
create policy finance_attempt_read on public.payment_attempts for select to authenticated using(public.tra_has_permission('payments.manage'));
create policy finance_event_read on public.payment_events for select to authenticated using(public.tra_has_permission('payments.manage'));
create policy finance_refund_read on public.refund_requests for select to authenticated using(public.tra_has_permission('payments.manage'));
create policy finance_ledger_read on public.financial_ledger_entries for select to authenticated using(public.tra_has_permission('payments.manage') or public.tra_has_permission('settlements.manage'));
create policy commission_party_read on public.intermediary_commissions for select to authenticated using(public.tra_has_permission('settlements.manage') or exists(select 1 from public.intermediary_profiles i where i.id=intermediary_id and i.user_id=auth.uid()));
create policy operations_exception_read on public.operational_exceptions for select to authenticated using(public.tra_has_permission('reports.view'));

do $$declare t text;begin foreach t in array array['wishlist_items','recently_viewed_artworks','shopping_bags','shopping_bag_items','offers','offer_events','artwork_reservations','payment_intents','payment_attempts','payment_events','refund_requests','financial_ledger_entries','intermediary_commissions','settlement_events','shipment_events','certificate_events','notifications','notification_preferences','notification_deliveries','private_media_assets','private_media_access_events','operational_exceptions'] loop execute format('revoke all on public.%I from anon,authenticated',t);execute format('grant select on public.%I to authenticated',t);end loop;end$$;

create or replace function public.tra_financial_immutable() returns trigger language plpgsql set search_path='' as $$begin raise exception 'FINANCIAL_RECORD_IMMUTABLE';end$$;
create trigger ledger_immutable before update or delete on public.financial_ledger_entries for each row execute function public.tra_financial_immutable();
create trigger payment_events_immutable before update or delete on public.payment_events for each row execute function public.tra_financial_immutable();

create or replace function public.tra_toggle_wishlist(p_artwork_id uuid) returns boolean language plpgsql security definer set search_path=public,auth,pg_temp as $$declare u uuid:=auth.uid();begin if not public.tra_account_is_active(u) then raise exception 'ACCOUNT_INACTIVE';end if;if not exists(select 1 from artworks where id=p_artwork_id and status='published') then raise exception 'ARTWORK_UNAVAILABLE';end if;delete from wishlist_items where user_id=u and artwork_id=p_artwork_id;if found then return false;end if;insert into wishlist_items(user_id,artwork_id) values(u,p_artwork_id);return true;end$$;
create or replace function public.tra_record_recent_view(p_artwork_id uuid) returns void language plpgsql security definer set search_path=public,auth,pg_temp as $$declare u uuid:=auth.uid();begin if not public.tra_account_is_active(u) then raise exception 'ACCOUNT_INACTIVE';end if;insert into recently_viewed_artworks(user_id,artwork_id) values(u,p_artwork_id) on conflict(user_id,artwork_id) do update set last_viewed_at=clock_timestamp(),view_count=recently_viewed_artworks.view_count+1;delete from recently_viewed_artworks where user_id=u and artwork_id in(select artwork_id from recently_viewed_artworks where user_id=u order by last_viewed_at desc offset 50);end$$;
create or replace function public.tra_clear_recently_viewed() returns void language sql security definer set search_path='' as $$delete from public.recently_viewed_artworks where user_id=auth.uid() and public.tra_account_is_active()$$;
create or replace function public.tra_change_shopping_bag(p_artwork_id uuid,p_operation text) returns void language plpgsql security definer set search_path=public,auth,pg_temp as $$declare u uuid:=auth.uid();b uuid;begin if not public.tra_account_is_active(u) or p_operation not in ('add','remove') then raise exception 'REQUEST_DENIED';end if;insert into shopping_bags(user_id) values(u) on conflict(user_id) do update set updated_at=clock_timestamp() returning id into b;if p_operation='add' then if not exists(select 1 from artworks where id=p_artwork_id and status='published') then raise exception 'ARTWORK_UNAVAILABLE';end if;insert into shopping_bag_items(bag_id,artwork_id,price_seen_paise) select b,id,final_price_paise from artworks where id=p_artwork_id on conflict do nothing;else delete from shopping_bag_items where bag_id=b and artwork_id=p_artwork_id;end if;end$$;
create or replace function public.tra_create_offer(p_artwork_id uuid,p_amount_minor bigint,p_currency char(3),p_expires_at timestamptz,p_message text) returns uuid language plpgsql security definer set search_path=public,auth,pg_temp as $$declare u uuid:=auth.uid();o uuid;begin if not public.tra_account_is_active(u) or p_amount_minor<=0 or p_expires_at<=clock_timestamp() or p_expires_at>clock_timestamp()+interval '30 days' then raise exception 'INVALID_OFFER';end if;perform pg_advisory_xact_lock(hashtextextended('offer:'||p_artwork_id::text||':'||u::text,0));if not exists(select 1 from artworks where id=p_artwork_id and status='published' and not public.tra_owns_artist(artist_id)) then raise exception 'ARTWORK_UNAVAILABLE';end if;insert into offers(artwork_id,buyer_user_id,currency,amount_paise,current_amount_paise,expires_at,message) values(p_artwork_id,u,p_currency,p_amount_minor,p_amount_minor,p_expires_at,nullif(btrim(p_message),'')) returning id into o;insert into offer_events(offer_id,actor_id,action,to_status,amount_paise) values(o,u,'submit','submitted',p_amount_minor);return o;end$$;
create or replace function public.tra_transition_offer(p_offer_id uuid,p_action text,p_expected_version bigint,p_amount_minor bigint,p_note text) returns text language plpgsql security definer set search_path=public,auth,pg_temp as $$declare u uuid:=auth.uid();o offers%rowtype;a artworks%rowtype;next_status text;buyer_record uuid;sale_record uuid;allowed boolean:=false;begin if not public.tra_account_is_active(u) then raise exception 'ACCOUNT_INACTIVE';end if;select * into o from offers where id=p_offer_id for update;if not found or o.state_version<>p_expected_version then raise exception 'STALE_OFFER';end if;if o.expires_at<=clock_timestamp() and p_action<>'expire' then raise exception 'OFFER_EXPIRED';end if;select * into a from artworks where id=o.artwork_id for update;allowed:=o.buyer_user_id=u and p_action in ('withdraw','accept','reject') or public.tra_owns_artist(a.artist_id) and p_action in ('counter','accept','reject') or public.tra_has_permission('offers.manage') and p_action in ('review','send_to_artist','counter','accept','reject','expire');if not allowed then raise exception 'PERMISSION_DENIED';end if;next_status:=case when p_action='review' and o.status='submitted' then 'under_review' when p_action='send_to_artist' and o.status='under_review' then 'sent_to_artist' when p_action='counter' and o.status in ('sent_to_artist','countered') and p_amount_minor>0 then 'countered' when p_action='accept' and o.status in ('sent_to_artist','countered') then 'accepted' when p_action='reject' and o.status in ('submitted','under_review','sent_to_artist','countered') then 'rejected' when p_action='withdraw' and o.status in ('submitted','under_review','sent_to_artist','countered') then 'withdrawn' when p_action='expire' and o.status in ('submitted','under_review','sent_to_artist','countered') then 'expired' else null end;if next_status is null then raise exception 'INVALID_OFFER_TRANSITION';end if;if next_status='accepted' then if a.status<>'published' then raise exception 'ARTWORK_UNAVAILABLE';end if;update artwork_reservations set status='expired',updated_at=clock_timestamp() where artwork_id=a.id and status in ('pending','active') and expires_at<=clock_timestamp();if exists(select 1 from artwork_reservations where artwork_id=a.id and status in ('pending','active') and user_id<>o.buyer_user_id) then raise exception 'ARTWORK_ALREADY_RESERVED';end if;insert into buyers(user_id,full_name,email) select o.buyer_user_id,coalesce(nullif(p.display_name,''),'Collector'),au.email from auth.users au left join profiles p on p.id=au.id where au.id=o.buyer_user_id on conflict(user_id) do update set email=excluded.email returning id into buyer_record;insert into sales(sale_reference,order_kind,artwork_id,artist_id,buyer_id,buyer_user_id,status,currency,agreed_price_paise,offer_id,price_snapshot,created_by) values('TRA-'||upper(substr(replace(gen_random_uuid()::text,'-',''),1,12)),'offer',a.id,a.artist_id,buyer_record,o.buyer_user_id,'reserved',o.currency,o.current_amount_paise,o.id,jsonb_build_object('artwork_title',a.title,'amount_paise',o.current_amount_paise,'currency',o.currency),u) returning id into sale_record;insert into artwork_reservations(artwork_id,user_id,offer_id,sale_id,source,status,expires_at) values(a.id,o.buyer_user_id,o.id,sale_record,'offer','converted',clock_timestamp());update offers set accepted_sale_id=sale_record where id=o.id;end if;update offers set status=next_status,current_amount_paise=coalesce(p_amount_minor,current_amount_paise),state_version=state_version+1,updated_at=clock_timestamp() where id=o.id;insert into offer_events(offer_id,actor_id,action,from_status,to_status,amount_paise,note) values(o.id,u,p_action,o.status,next_status,coalesce(p_amount_minor,o.current_amount_paise),nullif(btrim(p_note),''));return next_status;end$$;
create or replace function public.tra_create_artwork_reservation(p_artwork_id uuid,p_expires_at timestamptz,p_source text) returns uuid language plpgsql security definer set search_path=public,auth,pg_temp as $$declare u uuid:=auth.uid();r uuid;begin if not public.tra_account_is_active(u) or p_expires_at<=clock_timestamp() or p_expires_at>clock_timestamp()+interval '7 days' then raise exception 'INVALID_RESERVATION';end if;perform pg_advisory_xact_lock(hashtextextended('reservation:'||p_artwork_id::text,0));update artwork_reservations set status='expired',updated_at=clock_timestamp() where artwork_id=p_artwork_id and status in ('pending','active') and expires_at<=clock_timestamp();if not exists(select 1 from artworks where id=p_artwork_id and status='published') then raise exception 'ARTWORK_UNAVAILABLE';end if;insert into artwork_reservations(artwork_id,user_id,source,expires_at) values(p_artwork_id,u,p_source,p_expires_at) returning id into r;return r;exception when unique_violation then raise exception 'ARTWORK_ALREADY_RESERVED';end$$;
create or replace function public.tra_mark_notifications_read(p_ids uuid[]) returns integer language plpgsql security definer set search_path=public,auth,pg_temp as $$declare n integer;begin if not public.tra_account_is_active() then raise exception 'ACCOUNT_INACTIVE';end if;update notifications set read_at=coalesce(read_at,clock_timestamp()) where user_id=auth.uid() and (cardinality(p_ids)=0 or id=any(p_ids));get diagnostics n=row_count;return n;end$$;
create or replace function public.tra_request_refund(p_sale_id uuid,p_amount_minor bigint,p_reason text) returns uuid language plpgsql security definer set search_path=public,auth,pg_temp as $$declare r uuid;paid bigint;refunded bigint;begin if not public.tra_has_permission('payments.manage') or char_length(btrim(p_reason))<10 then raise exception 'PERMISSION_DENIED';end if;select gross_paise into paid from sales where id=p_sale_id and status in ('paid','fulfilment','completed','refunded') for update;if not found then raise exception 'SALE_NOT_REFUNDABLE';end if;select coalesce(sum(amount_paise),0) into refunded from refund_requests where sale_id=p_sale_id and status in ('requested','approved','processing','succeeded');if p_amount_minor<=0 or p_amount_minor>paid-refunded then raise exception 'INVALID_REFUND_AMOUNT';end if;insert into refund_requests(sale_id,amount_paise,reason,requested_by,idempotency_key) values(p_sale_id,p_amount_minor,btrim(p_reason),auth.uid(),gen_random_uuid()) returning id into r;return r;end$$;
create or replace function public.tra_verify_certificate(p_token text) returns table(reference_code text,artwork_id uuid,artist_name text,issue_date date,certificate_version integer,status text,revoked boolean) language sql stable security definer set search_path='' as $$select c.reference_code,c.artwork_id,coalesce(ap.display_name,'Artist'),c.issue_date,c.certificate_version,c.status::text,c.revoked_at is not null from public.certificates c join public.artist_profiles ap on ap.id=c.issuer_artist_id where c.verification_token_hash=encode(extensions.digest(p_token,'sha256'),'hex') and p_token ~ '^tra_coa_[A-Za-z0-9_-]{43}$'$$;
create or replace function public.tra_post_ledger_transaction(p_transaction_id uuid,p_idempotency_key text,p_entries jsonb) returns uuid language plpgsql security definer set search_path=public,auth,pg_temp as $$declare debit bigint;credit bigint;e jsonb;begin if auth.role()<>'service_role' and not public.tra_has_permission('payments.manage') then raise exception 'PERMISSION_DENIED';end if;select coalesce(sum((x->>'amount_paise')::bigint) filter(where x->>'direction'='debit'),0),coalesce(sum((x->>'amount_paise')::bigint) filter(where x->>'direction'='credit'),0) into debit,credit from jsonb_array_elements(p_entries)x;if debit<=0 or debit<>credit then raise exception 'LEDGER_NOT_BALANCED';end if;for e in select * from jsonb_array_elements(p_entries) loop insert into financial_ledger_entries(transaction_id,sale_id,payment_intent_id,entry_type,account,direction,amount_paise,currency,idempotency_key,reference) values(p_transaction_id,nullif(e->>'sale_id','')::uuid,nullif(e->>'payment_intent_id','')::uuid,e->>'entry_type',e->>'account',e->>'direction',(e->>'amount_paise')::bigint,coalesce(e->>'currency','INR'),p_idempotency_key,e->>'reference');end loop;return p_transaction_id;end$$;

revoke all on function public.tra_toggle_wishlist(uuid),public.tra_record_recent_view(uuid),public.tra_clear_recently_viewed(),public.tra_change_shopping_bag(uuid,text),public.tra_create_offer(uuid,bigint,char,timestamptz,text),public.tra_transition_offer(uuid,text,bigint,bigint,text),public.tra_create_artwork_reservation(uuid,timestamptz,text),public.tra_mark_notifications_read(uuid[]),public.tra_request_refund(uuid,bigint,text),public.tra_verify_certificate(text),public.tra_post_ledger_transaction(uuid,text,jsonb) from public;
grant execute on function public.tra_toggle_wishlist(uuid),public.tra_record_recent_view(uuid),public.tra_clear_recently_viewed(),public.tra_change_shopping_bag(uuid,text),public.tra_create_offer(uuid,bigint,char,timestamptz,text),public.tra_transition_offer(uuid,text,bigint,bigint,text),public.tra_create_artwork_reservation(uuid,timestamptz,text),public.tra_mark_notifications_read(uuid[]),public.tra_request_refund(uuid,bigint,text) to authenticated;
grant execute on function public.tra_verify_certificate(text) to anon,authenticated;
